package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class CollectingAndThenTest {

    @Test
    void collectThenWrapUnmodifiable() {
        List<String> ids = List.of("SAV2001", "CUR3001", "FD4001").stream()
            .filter(id -> !id.startsWith("FD"))
            .collect(Collectors.collectingAndThen(
                     Collectors.toList(), Collections::unmodifiableList));

        assertThat(ids).containsExactly("SAV2001", "CUR3001");
        assertThatThrownBy(() -> ids.add("X"))
            .isInstanceOf(UnsupportedOperationException.class);
    }
}
