// ─── Test ───
@Test void collectingAndThenUnmodifiable() {
    List<String> result = Stream.of("A", "B")
        .collect(Collectors.collectingAndThen(Collectors.toList(), Collections::unmodifiableList));
    assertThatThrownBy(() -> result.add("C")).isInstanceOf(UnsupportedOperationException.class);
}

@Test void collectingAndThenUnwrapsOptional() {
    String max = Stream.of(1, 5, 3)
        .collect(Collectors.collectingAndThen(
            Collectors.maxBy(Comparator.naturalOrder()),
            opt -> opt.map(String::valueOf).orElse("NONE")));
    assertThat(max).isEqualTo("5");
}

@Test void collectingAndThenAsDownstream() {
    record Item(String cat, int val) {}
    Map<String, Integer> maxPerCat = List.of(new Item("A", 10), new Item("A", 30), new Item("B", 20))
        .stream().collect(Collectors.groupingBy(Item::cat,
            Collectors.collectingAndThen(
                Collectors.maxBy(Comparator.comparingInt(Item::val)),
                opt -> opt.map(Item::val).orElse(0))));
    assertThat(maxPerCat).containsEntry("A", 30).containsEntry("B", 20);
}
